import{_ as a,o as t,c as e,ag as s}from"./chunks/framework.DUTPmUpA.js";const d=JSON.parse('{"title":"Основы частиц","description":"","frontmatter":{"title":"Основы частиц","author":"kritth","steamId":"76561198055627364","date":"05.02.2015"},"headers":[],"relativePath":"assets/particles/particle-basics.md","filePath":"assets/particles/particle-basics.md"}'),b={name:"assets/particles/particle-basics.md"};function i(c,r,l,p,o,_){return t(),e("div",null,[...r[0]||(r[0]=[s('<ul><li></li></ul><h1 id="основы-частиц" tabindex="-1">Основы частиц <a class="header-anchor" href="#основы-частиц" aria-label="Permalink to &quot;Основы частиц&quot;">​</a></h1><p> Поэтому многие люди спрашивали меня о создании частиц и рабочем процессе, поскольку руководство предоставлено Steam (или кто-то, что размещен на сайте разработчика Valve), похоже, в какой-то момент остановился. Поскольку я сегодня я не могу выполнить слишком много сложной работы, я напишу несколько руководств, чтобы люди могли начать работу погружение в частицы. </p><p> Также обратите внимание, что в некоторых реализациях системы частиц могут использоваться сценарии Lua, если это очень сложная система. Поэтому время от времени вам будут полезны базовые сценарии Lua. </p><p>Вот список функций, рассматриваемых в этом руководстве: </p><h3>Рендерер</h3> - Рендеринг спрайтов [НЗП] <br> - Рендеринг моделей [НЗП] <br> - Рендеринг спрайта [WIP] <br> - Рендеринг веревки [НЗП] <br> - Рендеринг отложенного света [WIP] <br><h3>Оператор</h3> - Распад продолжительности жизни <br> - Альфа-затухание и распад <br> - Цвет выцветает <br> - Движение базовое <br> - Шкала радиуса <br> - Место движения на земле [НЗП] <br> - Скалярный/векторный шум [WIP] <br> - Нормализованный вектор [НЗП] <br> - Осциллирующий скаляр/вектор [НЗП] <br> - Переназначение контрольной точки на скаляр/вектор/скорость [НЗП] <br> - Базовая ротация [НЗП] <br> - Ориентация вращения относительно CP [WIP] <br> - Ориентация вращения в 2-м направлении [НЗП] <br> - Вращение, отклонение от курса/крен [НЗП] <br> - Наследовать атрибут родительской частицы [НЗП] <br><h3>Инициализатор</h3> - Альфа случайный <br> - Цвет случайный <br> - Пожизненный случайный <br> - Радиус случайный <br> - Положение вдоль кольца <br> - Положение внутри сферы случайное <br>',60)])])}const h=a(b,[["render",i]]);export{d as __pageData,h as default};
